from itertools import combinations
from collections import defaultdict
from sympy import Matrix, ZZ
from sympy.matrices.normalforms import smith_normal_form

LOW=(2,2,0,0); UP=(4,4,4,4)
def norm(a):
    return tuple(x for x in a if x)
def size(a): return sum(a)
def parts_box():
    out=[]
    def rec(prev,k,a):
        if k==4:
            b=tuple(a)
            if b[0]>=2 and b[1]>=2: out.append(b)
            return
        for x in range(min(prev,4),-1,-1): rec(x,k+1,a+[x])
    rec(4,0,[])
    return sorted(out,key=lambda z:(size(z),z), reverse=False)
P=parts_box()
bydeg=defaultdict(list)
for x in P: bydeg[size(x)].append(x)
# horizontal t-strip test mu/lambda, with mu subset lambda; conjugate differences at most 1
def pieri(mu,la,t):
    m=mu+(0,)*(4-len(mu)); l=la+(0,)*(4-len(la))
    if any(m[i]>l[i] for i in range(4)) or size(la)-size(mu)!=t:return False
    # conjugate column increments <=1
    for col in range(1,5):
        if sum(z>=col for z in l)-sum(z>=col for z in m)>1:return False
    return True

def sdiag(A):
    if not A: return []
    D=smith_normal_form(Matrix(A),domain=ZZ)
    return [abs(int(D[i,i])) for i in range(min(D.rows,D.cols)) if D[i,i]!=0]
print('CASE i=j=p=c=2; q=r=4; J basis: (2,2) subset lambda subset (4,4,4,4).')
for d in range(4,17):
    cols=bydeg[d]
    rows=[]; labels=[]
    for t in range(1,5):
        for mu in bydeg[d-t]:
            row=[int(pieri(mu,la,t)) for la in cols]
            if any(row): rows.append(row); labels.append((t,mu))
    A=Matrix(rows) if rows else Matrix(0,len(cols),[])
    D=smith_normal_form(A,domain=ZZ) if rows else Matrix(0,len(cols),[])
    diag=sdiag(rows)
    rank=len(diag)
    qdiag=diag + [0]*(len(cols)-rank)
    print('\nDEGREE',d)
    print('COLUMNS', [norm(x) for x in cols])
    print('ROWS', [(t,norm(mu),row) for (t,mu),row in zip(labels,rows)])
    print('SHAPE',len(rows),'x',len(cols),'RANK',rank,'SNF',diag,'Q_SNF',qdiag)
